#include <benchmark/benchmark.h>
#include <cbor/cbor.hpp>
#include <algorithm>
#include <cstdlib>
#include <string>

static cbor::lazy map_of(int const pairs)
{
    std::string m;
    m += static_cast<char>(0xb8);
    m += static_cast<char>(pairs);
    for (int i = 0; i < pairs; ++i) {
        std::string const k = "k" + std::to_string(1000 + i);
        m += static_cast<char>(0x60 + k.size());
        m += k;
        m += static_cast<char>(i % 24);
    }
    return *cbor::lazy::from(m);
}

static cbor::lazy const l = map_of(PAIRS);
static std::string const wanted = "k" + std::to_string(1000 + PAIRS - 1);

static void run(benchmark::State &state)
{
    auto const entries = *l.entries();
    for (auto _ : state) {
#if defined(ARM_STATIC)
        auto const found = cbor::lazy::find(entries.begin(), std::default_sentinel, wanted);
        if (!found || *found == std::default_sentinel) [[unlikely]]
            std::abort();
        auto at = *found;
        benchmark::DoNotOptimize(at);
#else
        auto found = std::ranges::find(entries, std::string_view(wanted), [](auto const &e) {
            if (!e) [[unlikely]]
                return std::string_view{};
            auto const k = e->first.template get<std::string_view>();
            return k ? **k : std::string_view{};
        });
        if (found == entries.end()) [[unlikely]]
            std::abort();
        benchmark::DoNotOptimize(found);
#endif
        benchmark::ClobberMemory();
    }
}
BENCHMARK(run);
BENCHMARK_MAIN();
